void PrintSMInfo ( PrintDest_t * dest , int indent , const SM_INFO * pSMInfo , IB_LID lid ) { if ( lid ) { PrintFunc ( dest , "%*sLID: 0x%04x PortGuid: 0x%016" PRIx64 " State: %11s\n" , indent , "" , lid , pSMInfo -> GUID , IbSMStateToText ( pSMInfo -> s . SMState ) ) ; } else { PrintFunc ( dest , "%*sPortGuid: 0x%016" PRIx64 " State: %11s\n" , indent , "" , pSMInfo -> GUID , IbSMStateToText ( pSMInfo -> s . SMState ) ) ; } } 